def check_equation(y, z):
    # Equation: 8 + y^3 + z^3 - 4*y^2*z^2 = 0
    return 8 + y**3 + z**3 - 4 * (y**2) * (z**2)

solutions = []
Z_MAX = 100

# Start y from 2, since x=2 and x <= y
y = 2
while True:
    # Determine the minimum z based on constraints:
    # 1. z >= y
    # 2. 4y^2 <= 3z  => z >= 4*y^2 / 3
    min_z = max(y, (4 * y**2 + 2) // 3) # Use ceiling division for integers

    if min_z > Z_MAX:
        # If the minimum required z already exceeds the search limit, stop iterating y
        break

    z = min_z
    while z <= Z_MAX:
        if check_equation(y, z) == 0:
            solutions.append((2, y, z))
        z += 1

    y += 1

# Print results
print("--- Search Results for x=2 (z <= 100) ---")
if solutions:
    print("Solutions found:")
    for sol in solutions:
        print(sol)
else:
    print("No solutions found in the specified range.")

